namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            int orderQty = CalculateOrderQuantity(item, season);
            if (orderQty <= 0 || string.IsNullOrEmpty(item.Sku))
                continue;

            RecordOrderResult(plan, item, supplier, orderQty);
        }

        return plan;
    }

    private static int CalculateOrderQuantity(StockItem item, int season)
    {
        if (item.OnHand < 0)
            return 0;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return 0;

        int deficit = item.ReorderPoint - available;
        int orderQty;
        if (deficit <= 0)
            orderQty = 0;
        else if (deficit < 10)
            orderQty = 10;
        else if (deficit < 100)
            orderQty = deficit;
        else
            orderQty = deficit + 50;

        if (season == 4 && orderQty > 0)
            orderQty = (int)(orderQty * 1.5);
        else if (season == 1)
            orderQty /= 2;

        return orderQty;
    }

    private static void RecordOrderResult(
        ICollection<string> plan,
        StockItem item,
        ISupplier supplier,
        int orderQty)
    {
        bool placed = supplier.PlaceOrder(item.Sku, orderQty);
        if (placed && orderQty > 200)
            plan.Add($"{item.Sku}:LARGE:{orderQty}");
        else if (placed)
            plan.Add($"{item.Sku}:{orderQty}");
        else
            plan.Add($"{item.Sku}:FAILED");
    }
}
